using TechTalk.SpecFlow;\nusing AutomationFramework.UI.BusinessLogic;\nusing AutomationFramework.Core.Config;\nusing OpenQA.Selenium;\nusing FluentAssertions;\n\nnamespace AutomationFramework.UI.StepDefinitions\n{\n    [Binding]\n    public class BlazeDemoSteps\n    {\n        private readonly IWebDriver _driver;\n        private readonly BlazeDemoBusinessLogic _blazeDemoBusinessLogic;\n\n        public BlazeDemoSteps(ScenarioContext scenarioContext)\n        {\n            _driver = (IWebDriver)scenarioContext[\"WebDriver\"];\n            _blazeDemoBusinessLogic = new BlazeDemoBusinessLogic(_driver);\n        }\n\n        [Given(@\"I navigate to BlazeDemo homepage\")]\n        public void GivenINavigateToBlazeDemoHomepage()\n        {\n            var url = ConfigManager.GetConfigValue<string>(\"BlazeDemoUrl\");\n            _driver.Navigate().GoToUrl(url);\n        }\n\n        [When(@\"I select '(.*)' as the departure city and '(.*)' as the destination city\")]\n        public void WhenISelectCities(string departureCity, string destinationCity)\n        {\n            _blazeDemoBusinessLogic.SelectCities(departureCity, destinationCity);\n        }\n\n        [When(@\"I click on 'Find Flights'\")]\n        public void WhenIClickOnFindFlights()\n        {\n            _blazeDemoBusinessLogic.ClickFindFlights();\n        }\n\n        [Then(@\"I should see a list of available flights\")]\n        public void ThenIShouldSeeAListOfAvailableFlights()\n        {\n            _blazeDemoBusinessLogic.VerifyFlightsListVisible().Should().BeTrue(\"Flights list should be visible after a successful search.\");\n        }\n\n        [Given(@\"I have searched for flights from '(.*)' to '(.*)'\")]\n        public void GivenIHaveSearchedForFlights(string departureCity, string destinationCity)\n        {\n            GivenINavigateToBlazeDemoHomepage();\n            WhenISelectCities(departureCity, destinationCity);\n            WhenIClickOnFindFlights();\n        }\n\n        [When(@\"I select the first available flight\")]\n        public void WhenISelectTheFirstAvailableFlight()\n        {\n            _blazeDemoBusinessLogic.SelectFirstAvailableFlight();\n        }\n\n        [When(@\"I enter passenger details\")]\n        public void WhenIEnterPassengerDetails()\n        {\n            _blazeDemoBusinessLogic.EnterPassengerDetails();\n        }\n\n        [When(@\"I do not enter passenger details\")]\n        public void WhenIDoNotEnterPassengerDetails()\n        {\n            // Intentionally left blank to simulate not entering details\n        }\n\n        [When(@\"I click on 'Purchase Flight'\")]\n        public void WhenIClickOnPurchaseFlight()\n        {\n            _blazeDemoBusinessLogic.ClickPurchaseFlight();\n        }\n\n        [Then(@\"I should see a confirmation message\")]\n        public void ThenIShouldSeeAConfirmationMessage()\n        {\n            _blazeDemoBusinessLogic.VerifyConfirmationMessageVisible().Should().BeTrue(\"Confirmation message should be visible after a successful booking.\");\n        }\n\n        [Then(@\"I should see an error message\")]\n        public void ThenIShouldSeeAnErrorMessage()\n        {\n            _blazeDemoBusinessLogic.VerifyErrorMessageVisible().Should().BeTrue(\"Error message should be displayed after an unsuccessful operation.\");\n        }\n    }\n}\n